    /**
     * Originate to 200 OK; absent when not answered
     */
    amd_t200_ms?: number;
    amd_verdict?: 'unknown' | 'human' | 'voicemail' | 'carrier_vm' | 'ivr' | 'screener' | 'fax' | 'sit';
    answered_at?: string;
    assistant_id?: string;
    assistant_version?: number;
    attestation?: 'A' | 'B' | 'C';
    billable_ms?: number;
    /**
     * Part of billable_ms bridged to a human after a transfer
     */
    bridged_ms?: number;
    /**
     * Settled price of the bridged part in micro-USD, billed at the transfer_minute rate
     */
    bridged_price_micro?: number;
    call_id: string;
    /**
     * Detail only: set when the caller's number is on the workspace block list
     */
    caller_blocked?: CallerBlockRef;
    /**
     * The contact name, else the name the caller gave
     */
    caller_name?: string;
    campaign_contact_id?: string;
    campaign_id?: string;
    cause?: string;
    codec?: 'G722' | 'PCMU' | 'PCMA' | 'opus';
    contact_id?: string;
    /**
     * Detail only: when the call content was permanently removed
     */
    content_removed_at?: string;
    /**
     * Why the agent got this call: inside hours, after hours, a holiday, or forwarded because the owner line was busy or unanswered
     */
    coverage?: 'open' | 'after_hours' | 'holiday' | 'forwarded_busy' | 'forwarded_no_answer';
    created_at: string;
    /**
     * Opaque; pass as after or before to page from this call
     */
    cursor?: string;
    direction: 'inbound' | 'outbound' | 'web_test';
    disclosure_played_at?: string;
    ended_at?: string;
    flagged?: CallFlag;
    /**
     * Flow agents only
     */
    flow?: CallFlow;
    from_e164?: string;
    hangup_by?: 'local' | 'remote' | 'system';
    /**
     * Detail only
     */
    latency?: CallLatency;
    mode: 'cascade' | 's2s';
    not_billed_reason?: 'short_call' | 'spam' | 'blocked' | 'agent_paused' | 'failed';
    number_id?: string;
    opted_out: boolean;
    /**
     * Fixed platform list; null while live and until analysis finishes
     */
    outcome?: 'booked_appointment' | 'rescheduled' | 'answered_question' | 'message_taken' | 'transferred_to_staff' | 'no_resolution' | 'carrier_error' | 'voicemail_left' | 'caller_hung_up' | 'no_answer' | 'line_busy' | 'spam_blocked' | 'caller_blocked';
    outcome_group?: 'handled' | 'needs_look' | 'not_connected';
    /**
     * machine: a machine answered and no message was left; phone_menu: the agent could not get through a phone menu
     */
    outcome_label?: 'machine' | 'phone_menu';
    /**
     * Every line was busy when the call came in: how it ended
     */
    overflow?: 'answered' | 'forwarded' | 'busy_message' | 'abandoned';
    /**
     * Billed time of the live-takeover phone legs dialled to your phones, on top of billable_ms
     */
    phone_leg_ms?: number;
    /**
     * Settled price of the phone legs in micro-USD at the transfer_minute rate; part of price_micro
     */
    phone_leg_price_micro?: number;
    /**
     * Settled price in micro-USD
     */
    price_micro?: number;
    /**
     * Detail only: each switch to a backup provider during the call, in order
     */
    provider_fallbacks?: Array<ProviderFallback>;
    /**
     * Detail only
     */
    quality?: CallQuality;
    /**
     * Automatic call quality check score
     */
    quality_score?: number;
    /**
     * Time the caller waited on hold for a free line; not billed
     */
    queue_wait_ms?: number;
    /**
     * Detail only
     */
    receipt?: CallReceipt;
    /**
     * Detail only
     */
    recording?: CallRecordingInfo;
    recording_allowed: boolean;
    recording_notice_played_at?: string;
    /**
     * Detail only: stored content was checked and sensitive data in it hidden
     */
    redacted?: boolean;
    /**
     * Detail only: categories checked and hidden in this call
     */
    redacted_categories?: Array<'card' | 'ssn' | 'dob' | 'bank' | 'gov_id'>;
    /**
     * Detail only: content is hidden until redaction finishes
     */
    redaction_pending?: boolean;
    /**
     * Caller sentiment from the post-call analysis, on every call
     */
    sentiment?: 'positive' | 'neutral' | 'negative';
    sip_code?: number;
    /**
     * widget: a website visitor called through the embedded widget (direction web_test)
     */
    source?: 'widget';
    spam_flagged: boolean;
    status: 'queued' | 'dialing' | 'ringing' | 'in_progress' | 'completed' | 'no_answer' | 'busy' | 'failed' | 'canceled' | 'rejected';
    successful?: boolean;
    /**
     * Short post-call summary, present on list items once analysed
     */
    summary?: string;
    tags: Array<string>;
    to_e164?: string;
    transfer?: CallTransfer;
    /**
     * Detail only: things the agent said it did that no tool result or booking backs up
     */
