export type CatalogModel = {
    defaults: {
        [key: string]: unknown;
    };
    /**
     * Plain description written by Larynth
     */
    description?: string;
    display_name: string;
    id: string;
    is_default: boolean;
    is_default_fallback: boolean;
    kind: 'stt' | 'llm' | 'tts' | 's2s' | 'embedding';
    languages: Array<string>;
    /**
     * Same value as latency_source
     */
    latency_basis?: 'live' | 'lab';
    /**
     * When the latency figures were last computed
     */
    latency_measured_at?: string;
    /**
     * The 95th percentile over the same samples as typical_latency_ms
     */
    latency_p95_ms?: number;
    /**
     * Number of samples behind typical_latency_ms and latency_p95_ms; 0 when no number exists
     */
    latency_samples: number;
    /**
     * live: our own calls of the last 7 days, written nightly once 50 turns exist. Turns are attributed per call to the single model of each kind the call used; calls that switched models mid-call (fallback) are excluded. lab: our direct probe from a US host, used until live data exists. Unset when no measurement exists
     */
    latency_source?: 'live' | 'lab';
    model_key: string;
    params_schema: {
        [key: string]: unknown;
    };
    /**
     * Added to the call-minute rate; 0 when no premium rate row exists. Equals what billing charges
     */
    premium_micro_per_min: number;
    provider_key: string;
    provider_name: string;
    /**
     * wer: 100 minus word error rate x10 on our benchmark corpus; eval: live-call eval pass rate; humanness: listening benchmark
     */
    quality_basis?: 'wer' | 'eval' | 'humanness';
    /**
     * 0 to 100, from our own measurement named by quality_basis; unset until measured
     */
    quality_score?: number;
    /**
     * The recommended model of its tier
     */
    recommended: boolean;
    /**
     * Date the vendor retires the model, YYYY-MM-DD; unset when no date is known
     */
    retires_on?: string;
    status: 'enabled' | 'deprecated';
    /**
     * Quality tier the editor shows by default; unset for models listed only under Advanced
     */
    tier?: 'fast' | 'balanced' | 'best';
    /**
     * Typical latency: STT is speech end to final transcript, LLM is time to first token, TTS is text to first audio
     */
    typical_latency_ms?: number;
    /**
     * Deprecated alias of typical_latency_ms, kept for one release
     *
     * @deprecated
     */
    typical_reply_ms?: number;
    /**
     * A flow step may pick this model (cascade LLMs only, at most 3 per flow)
     */
    usable_in_flows: boolean;
    wire_rates: Array<number>;
};

